import fs from 'node:fs';
// CarAdvance: Elofizeteses (Choice Auto-Abo) szekcio beszurasa a Berelheto panelbe.
// Build-safe: ha a panel nincs meg, nem csinal semmit (nincs regresszio).
const SEC_B64 = "";
const SEC = Buffer.from(SEC_B64, 'base64').toString('utf8');
const FILES = ['dist/autoink/index.html','dist/en/autoink/index.html'];
const ANCHOR = '<div class="autok-panel" id="panel-berelheto">';
let done = 0;
for (const f of FILES) {
  if (!fs.existsSync(f)) continue;
  let h = fs.readFileSync(f, 'utf8');
  if (h.indexOf('sub-intro') > -1) { console.log('[abo] mar beszurva: ' + f); continue; }
  const i = h.indexOf(ANCHOR);
  if (i < 0) { console.log('[abo] nincs panel-berelheto: ' + f); continue; }
  const at = i + ANCHOR.length;
  h = h.slice(0, at) + SEC + h.slice(at);
  fs.writeFileSync(f, h);
  done++;
  console.log('[abo] beszurva -> ' + f);
}
console.log('[abo] kesz (' + done + ' fajl modositva)');
